func:
// รับจาก 3 node อ่าน แยกตาม msg.topic: operator | times | counter
// ตั้งค่าการถอดรหัส (เปลี่ยนได้หลังเทียบกับหน้าจอ HMI)
const WORD_SWAP = true;      // ค่า 32-bit: HMI นี้เก็บ low word ก่อน (ยืนยันจาก FUXA: 32882 = ค่าจริง)
const BYTE_SWAP = false;     // ตัวอักษร Operator: false = high byte ก่อน
const TIME_MODE = "bytes";   // "bytes" | "bcd" | "dec"

const v = Array.isArray(msg.payload) ? msg.payload
        : (msg.payload && Array.isArray(msg.payload.data)) ? msg.payload.data : [];
const u32 = (a, b) => WORD_SWAP ? (b * 65536 + a) : (a * 65536 + b);

function chars(words) {
    let s = "";
    for (const w of words) {
        const hi = (w >> 8) & 255, lo = w & 255;
        for (const c of (BYTE_SWAP ? [lo, hi] : [hi, lo])) {
            if (c === 0) return s.trim();
            if (c >= 32 && c <= 126) s += String.fromCharCode(c);
        }
    }
    return s.trim();
}
function pair(w) {
    const hi = (w >> 8) & 255, lo = w & 255;
    if (TIME_MODE === "bcd") return [(hi >> 4) * 10 + (hi & 15), (lo >> 4) * 10 + (lo & 15)];
    if (TIME_MODE === "dec") return [Math.floor(w / 100), w % 100];
    return [hi, lo];
}
function hmiTime(words) {
    if (words.every(x => x === 0)) return "";
    const [y, mo] = pair(words[0]), [d, h] = pair(words[1]), [mi, s] = pair(words[2]);
    const p = n => String(n).padStart(2, "0");
    return `20${p(y)}-${p(mo)}-${p(d)} ${p(h)}:${p(mi)}:${p(s)}`;
}
const STATUS_TEXT = {0:"Idle",1:"Manual",2:"Semi-Auto",4:"Auto",8:"Adj. Mould",
                     17:"Manual Error",18:"Semi-Auto Error",19:"Adj. Mould Error",20:"Auto Error"};

const d = flow.get("cm_data") || {};
if (msg.topic === "operator" && v.length >= 10) {
    d.operator = chars(v.slice(0, 10));
} else if (msg.topic === "times" && v.length >= 6) {
    d.jobStart  = hmiTime(v.slice(0, 3));
    d.jobFinish = hmiTime(v.slice(3, 6));
    d.rawTimes  = v.slice(0, 6);
} else if (msg.topic === "counter" && v.length >= 6) {
    // 32879 cav | 32880-81 target | 32882-83 shot | 32884 status
    d.cavities    = v[0];
    d.targetShots = u32(v[1], v[2]);
    d.shotCount   = u32(v[3], v[4]);
    d.status      = v[5];
    d.statusText  = STATUS_TEXT[v[5]] || ("Unknown(" + v[5] + ")");
    d.rawShot     = [v[3], v[4]];
    flow.set("cm_lastOk", Date.now());   // ใช้ชุดนี้เป็นตัวบอกว่า HMI ยังตอบอยู่
} else {
    node.warn("ข้อมูลไม่ครบ topic=" + msg.topic + " len=" + v.length);
    return null;
}
flow.set("cm_data", d);
node.status({fill: "green", shape: "dot", text: msg.topic + " ok " + new Date().toLocaleTimeString("en-GB")});
msg.payload = d;
return msg;

// register 32970 = Cycle Time (ทศนิยม 1 ตำแหน่ง)
const v = Array.isArray(msg.payload) ? msg.payload
        : (msg.payload && Array.isArray(msg.payload.data)) ? msg.payload.data : [];
if (!v.length) return null;
flow.set("cm_cycle", v[0] / 10);
return null;

// สร้าง JSON ส่งไป CounterMachine.aspx
const MACHINE  = "MC7";
const STALE_MS = 10000;      // HMI ไม่ตอบเกิน 10 วินาที = OFF
const NO_TARGET = 99999999;  // ค่าเป้า 99,999,999 = ไม่ได้ตั้งเป้าบน HMI

const b      = flow.get("cm_data");
const lastOk = flow.get("cm_lastOk") || 0;
const online = !!b && (Date.now() - lastOk) < STALE_MS;

if (online) {
    msg.payload = {
        machine:     MACHINE,
        online:      true,
        power:       "ON",
        status:      b.status,
        statusText:  b.statusText,
        operator:    b.operator,
        shotCount:   b.shotCount,
        cycleTime:   flow.get("cm_cycle") ?? null,
        cavities:    b.cavities,
        targetShots: (b.targetShots > 0 && b.targetShots < NO_TARGET) ? b.targetShots : null,
        jobStart:    b.jobStart,
        jobFinish:   b.jobFinish,
        ts:          new Date().toISOString()
    };
} else {
    msg.payload = { machine: MACHINE, online: false, power: "OFF", ts: new Date().toISOString() };
}

msg.headers = { "Content-Type": "application/json" };
// ถ้าตั้ง API_KEY ในหน้า aspx ให้เปิดบรรทัดนี้:
// msg.headers["X-Api-Key"] = "ใส่คีย์";
// ไม่รอนาน: ถ้าเซิร์ฟเวอร์ไม่ตอบภายใน 4 วินาทีให้ตัดทิ้ง (กัน request ค้างสะสม)
msg.requestTimeout = 4000;
return msg;
